\label{Q:insertion}
Can one more cylinder of radius $\omega_n$ be added, for a total of $n+1$? The cylinders may be
rearranged, but they must be non-overlapping and touch the unit ball.

\label{Q:expansion}
Let $\omega'>\omega_n$. Can the $n$ cylinders be enlarged to the common radius $\omega'$ and rearranged
so that they are non-overlapping and touch the unit ball? For which $\omega'$ is the answer yes?

\label{lem:Pcylmono}
If $(n,\omega)\in\mathcal{P}_{\mathrm{cyl}}$, then $(n',\omega')\in\mathcal{P}_{\mathrm{cyl}}$ for every integer $n'\ge n$ and every
$\omega'\ge\omega$.

\label{thm:A}
For every $n\in\{3,4,5,6,7\}$ we have $(n,\omega_n)\in\mathcal{P}_{\mathrm{cyl}}$. Hence insertion is impossible for these
$n$.

\label{lem:linedist}
Let $\ell_i=\{\overrightarrow{p_i}+t \overrightarrow{v_i}:t\in\mathbb{R}\}$ for $i=1,2$. Then
\begin{align*}
\operatorname{dist}(\ell_1,\ell_2)=
\begin{cases}
\bigl| (\overrightarrow{p_2}-\overrightarrow{p_1})\cdot (\overrightarrow{v_1}\times \overrightarrow{v_2}) \bigr|\,/\,\|\overrightarrow{v_1}\times \overrightarrow{v_2}\|, & \text{if }\overrightarrow{v_1}\nparallel\overrightarrow{v_2},\\[3pt]
\bigl\|(\overrightarrow{p_2}-\overrightarrow{p_1})\times\overrightarrow{v_1}\bigr\|\,/\,\|\overrightarrow{v_1}\|, & \text{if }\overrightarrow{v_1}\parallel\overrightarrow{v_2}.
\end{cases}
\end{align*}

\label{def:D}
For $\tau\in(0,2)$ we define the \emph{safe zone} $\mathcal{D}(\tau)$ as the subset of $\operatorname{SO}(3)$ given by
\[ \mathcal{D}(\tau)=\{g\in\operatorname{SO}(3):\operatorname{dist}(\ell_0,\,g\cdot\ell_0)\ge\tau\}.\]

\label{def:nonOverlappingX}
A set $X\subseteq \operatorname{SO}(3)$ will be called \emph{non-overlapping} if
$g^{-1}g'\in\mathcal{D}$ whenever $g$ and $g'$ are two distinct elements of $X$.

\label{lem:monotone}
If $0<\tau'\le\tau<2$, then $\mathcal{D}(\tau)\subseteq\mathcal{D}(\tau')$, and consequently
$N_{\max}(\tau)\le N_{\max}(\tau')$.

\label{lem:OSIdentity}
Let $\ell$ and $\ell'$ be lines tangent to the unit sphere. Let
$(\overrightarrow{p},\overrightarrow{v},\overrightarrow{w})$ and
$(\overrightarrow{p'},\overrightarrow{v'},\overrightarrow{w'})$ be their associated orthonormal systems.
Then
\begin{align}
2\left(\overrightarrow{p}\cdot\overrightarrow{p'}\right)^2-2\left(\overrightarrow{w}\cdot\overrightarrow{w'}\right)^2
&=\left(\overrightarrow{v}\cdot\overrightarrow{w'}-\overrightarrow{w}\cdot\overrightarrow{v'}\right)^2
+\left(\left(\overrightarrow{p'}-\overrightarrow{p}\right)\cdot\left(\overrightarrow{v}\times\overrightarrow{v'}\right)\right)^2
-2\left\|\overrightarrow{v}\times\overrightarrow{v'}\right\|^2. \label{eqn:OSIdentity}
\end{align}

\label{lem:Cbeta}
For $\beta\in(0,\pi)$ all six pairwise distances in $\mathcal C_\beta$ are equal to $\sqrt2$. The
configuration $\mathcal C_0$ is the ring of four lines.

\label{def:pinwheel}
Let $N=2k\ge6$ be even and set $\gamma=\frac{2\pi}k=\frac{4\pi}N$. For a latitude
$\mu\in(-\frac\pi2,\frac\pi2)$ and longitude $\lambda$, let
\[
x(\mu,\lambda)=(\cos \mu\cos\lambda,\ \cos \mu\sin\lambda,\ \sin \mu)\in\mathbb{S}^2,
\]
and let $\overrightarrow{u}=\langle-\sin \mu\cos\lambda,\,-\sin \mu\sin\lambda,\,\cos \mu\rangle$ and
$\overrightarrow{t}=\langle-\sin\lambda,\,\cos\lambda,\,0\rangle$ be the unit tangent vectors at $x(\mu,\lambda)$ pointing north
and east. Given parameters $\varphi\in(0,\frac\pi2)$, $\delta\in(0,\frac\pi2)$ and
$\psi\in\mathbb{R}$, the pinwheel $P(N;\varphi,\delta,\psi)$ is the family of $N$ lines
tangent to $\mathbb{S}^2$ consisting of the \emph{up group}
\begin{align*}
\ell_j^{+}:\quad\text{tangent point }x(\varphi,\ j\gamma),\quad
\text{direction } \overrightarrow{v}=\cos\delta\,\overrightarrow{u}+\sin\delta\,\overrightarrow{t},\quad j=0,\dots,k-1,
\end{align*}
and the \emph{down group}
\begin{align*}
\ell_j^{-}:\quad\text{tangent point }x(-\varphi,\ j\gamma+\psi),\quad
\text{direction } \overrightarrow{v}=\cos\delta\,\overrightarrow{u}+\sin\delta\,\overrightarrow{t},\quad j=0,\dots,k-1.
\end{align*}

\label{lem:distances} Assume that $\varphi\in (0,\frac{\pi}{2})$, $\Delta\in [0,2\pi)$, 
 and $\delta\in (0,\frac{\pi}{2})$. The squares of the distances between $\ell^+(0)$ and $\ell^{\pm}(\Delta)$ satisfy
 \begin{align}
 \operatorname{dist}^2(\ell^+(0),\ell^+(\Delta))&= 
 \frac{4\cos^4\varphi\tan^2\delta \sin^2\frac{\Delta}2 }{
\left(\tan^2\delta+ \sin^2\varphi\right)
\cdot 
\left[ 1+\tan^2\delta -\sin^2\frac{\Delta}{2} \left(\tan^2\delta+ \sin^2\varphi\right)\right]
};
\label{eq:lemmaDistl1l2Plus}\\
 \operatorname{dist}^2(\ell^+(0),\ell^-(\Delta))&= 
 \frac{4\left(\sin\varphi\tan\delta +\tan\frac{\Delta}{2}\right)^2}{
 \cos^2\varphi(1+\tan^2\delta) + \left(    \sin\varphi\tan\delta+ \tan\frac{\Delta}{2}
\right)^2}\quad\text{for }\Delta\neq\pi,
 \label{eq:lemmaDistl1l2Minus}
 \end{align}
 while $\operatorname{dist}(\ell^+(0),\ell^-(\Delta))=2$ for $\Delta=\pi$.

\label{lem:tailstar2}
Let $N\ge2s+4$ be even. If
\begin{align}\label{eq:tailstar2}
2\Bigl(1-\frac sN\Bigr)\Bigl(1-\frac{2\pi^2}{3N^2}\Bigr)\;\ge\;\frac1\Phi,
\end{align}
then \eqref{eq:same} holds with $\theta=\frac\pi{N-s}$. The left-hand side of
\eqref{eq:tailstar2} is strictly increasing in $N$, and \eqref{eq:tailstar2} holds for $s=1$,
$N=32$ and for $s=2$, $N=48$. Hence \eqref{eq:same} holds for all even $N\ge32$
(respectively $N\ge48$).

\label{lem:tailarc}
Let $N\ge2s+4$ be even, $\theta=\frac\pi{N-s}\le1$, and set
$\bar u=\sqrt{c_0}\,(\theta+\theta^3)$. If $\bar u^2<1+S^2T^2$ and
\begin{align}\label{eq:tailarc}
N\,\bar u\;\le\;\pi\bigl(1+S^2T^2-\bar u^2\bigr),
\end{align}
then \eqref{eq:cross} holds with $\theta=\frac\pi{N-s}$. The left-hand side of
\eqref{eq:tailarc} is strictly decreasing in $N$ and the right-hand side is increasing, so
\eqref{eq:tailarc}, once true, remains true for all larger $N$. It holds for $s=1$, $N=32$ and
for $s=2$, $N=48$, hence for all even $N\ge32$ (respectively $N\ge48$).

By \ref{E:tan}, $u^*=\sqrt{c_0}\tan\theta\le\bar u$, so $u^{*2}\le\bar u^2<1+S^2T^2$. By
\ref{E:atan} (the product $(ST+u^*)(ST-u^*)=S^2T^2-u^{*2}>-1$),
\begin{align*}
\arctan(ST+u^*)-\arctan(ST-u^*)&=\arctan\frac{2u^*}{1+S^2T^2-u^{*2}}
\le\frac{2u^*}{1+S^2T^2-u^{*2}}\\
&\le\frac{2\bar u}{1+S^2T^2-\bar u^2}\le\frac{2\pi}N,
\end{align*}
using \ref{E:mono} and \eqref{eq:tailarc}. For the monotonicity,
$N\bar u=\pi\sqrt{c_0}\,\frac N{N-s}\,\bigl(1+\theta^2\bigr)$ is a product of positive strictly
decreasing factors of $N$, while $\bar u$ itself decreases, so $\pi(1+S^2T^2-\bar u^2)$ increases.
The two threshold cases are in Table~\ref{tab:checks}.

\label{def:ratline}
A \emph{rational tangent line} is a pair $(P,\overrightarrow{V})$ of integer vectors $P=(A,B,C,E)\in\mathbb{Z}^4$ and
$\overrightarrow{V}=(V_0,V_1,V_2)\in\mathbb{Z}^3\setminus\{0\}$ with
\begin{align}\label{eq:W12}
\text{(W1)}\quad A^2+B^2+C^2=E^2,\ \ E>0,\quad
\text{(W2)}\quad AV_0+BV_1+CV_2=0,\ \ \overrightarrow{V}\ne0 .
\end{align}
It denotes the line $\ell(P,\overrightarrow{V})=\{\overrightarrow{p}+t\overrightarrow{V}:t\in\mathbb{R}\}$ with $\overrightarrow{p}=\frac1E(A,B,C)$, which by (W1) and
(W2) is tangent to the unit sphere at $\overrightarrow{p}$.

\label{lem:ratdist}
Let $\ell=\ell(P,\overrightarrow{V})$ and $\ell'=\ell(P',\overrightarrow{V'})$ be rational tangent lines with tangency points
$\overrightarrow{p},\overrightarrow{p'}$. Define $\overrightarrow{c}=\overrightarrow{V}\times \overrightarrow{V'}$ and $\overrightarrow{\Delta}=\overrightarrow{p'}-\overrightarrow{p}$. Then $\operatorname{dist}(\ell,\ell')^2$ is the rational
number
\begin{align}
\frac{(\overrightarrow{c}\cdot\overrightarrow{\Delta})^2}{\|\overrightarrow{c}\|^2}\quad\text{if }\overrightarrow{c}\ne0,\quad
\Bigl\|\overrightarrow{\Delta}-\frac{\overrightarrow{\Delta}\cdot \overrightarrow{V}}{\|\overrightarrow{V}\|^2}\,\overrightarrow{V}\Bigr\|^{2}\quad\text{if }\overrightarrow{c}=0 . \label{eqn:ratdist}
\end{align}

\label{def:DB}
For a sequence $\overrightarrow C=(C_\ell)_{\ell=1}^{L}$ of symmetric positive-semidefinite matrices
$C_\ell\in\mathbb{R}^{n_\ell\times n_\ell}$, we define its supremum over the safe zone as
\begin{align*}
\operatorname{S}\bigl(\overrightarrow C\bigr)\;=\;\sup_{g\in\mathcal{D}(\tau)}\;\sum_{\ell=1}^{L}
\operatorname{tr}\!\Bigl(D_\ell^{-1}C_\ell\,T^\ell(g)\Bigr).
\end{align*}

\label{thm:dbBound}
Let $\overrightarrow C=(C_\ell)_{\ell=1}^{L}$ be a sequence of symmetric positive-semidefinite
matrices $C_\ell\in\mathbb{R}^{n_\ell\times n_\ell}$. If $\operatorname{S}(\overrightarrow C)\le-1$, then
\begin{align}\label{eq:dbBound}
N_{\max}(\tau)\;\le\;1+\left\lfloor\sum_{\ell=1}^{L}\operatorname{tr}\bigl(D_\ell^{-1}C_\ell\bigr)\right\rfloor .
\end{align}

\label{lem:quat}
The following hold as polynomial identities in $\mathbb{Z}[p,q]$:
\begin{enumerate}[leftmargin=2.2em,label=(\alph*)]
\item $R(q)^\top R(q)=|q|^4 I$ and $\det R(q)=|q|^6$. In particular, $R(q)\in\operatorname{SO}(3)$ whenever
$|q|=1$;
\item $R(p*q)=R(p)\,R(q)$ and $|p*q|^2=|p|^2|q|^2$;
\item the ten products $q_aq_b$ $(0\le a\le b\le3)$ are $\mathbb{Z}$-linear combinations of $|q|^2$ and the
entries $R_{ij}$ of $R(q)$. Explicitly,
$4q_0^2=|q|^2+R_{11}+R_{22}+R_{33}$, $4q_1^2=|q|^2+R_{11}-R_{22}-R_{33}$,
$4q_2^2=|q|^2-R_{11}+R_{22}-R_{33}$, $4q_3^2=|q|^2-R_{11}-R_{22}+R_{33}$,
$4q_0q_1=R_{32}-R_{23}$, $4q_0q_2=R_{13}-R_{31}$, $4q_0q_3=R_{21}-R_{12}$,
$4q_1q_2=R_{12}+R_{21}$, $4q_1q_3=R_{13}+R_{31}$, $4q_2q_3=R_{23}+R_{32}$.
\end{enumerate}

\label{lem:cover2}
\leavevmode
\begin{enumerate}[leftmargin=2.2em,label=(\alph*)]
\item If $q,q'$ are unit quaternions with $R(q)=R(q')$, then $q'=\pm q$.
\item Every $g\in\operatorname{SO}(3)$ equals $R(q)$ for some unit quaternion $q$.
\end{enumerate}

\label{lem:nhNhHh}
Let $q\ne0$ and $g=|q|^{-2}R(q)$. Then
\begin{align}
\bigl\|\overrightarrow{e_1}\times g\overrightarrow{e_1}\bigr\|^{2}
&=\frac{4\bigl(q_0^{2}+q_1^{2}\bigr)\bigl(q_2^{2}+q_3^{2}\bigr)}{|q|^{4}}, \label{eq:NhExplicit}\\
\bigl(g\overrightarrow{e_3}-\overrightarrow{e_3}\bigr)\cdot\bigl(\overrightarrow{e_1}\times g\overrightarrow{e_1}\bigr)
&=\frac{-4\,q_1q_2}{|q|^{2}}, \label{eq:nhExplicit}\\
\bigl\|\bigl(g\overrightarrow{e_3}-\overrightarrow{e_3}\bigr)\times\overrightarrow{e_1}\bigr\|^{2}
&=\frac{4\Bigl[\bigl(q_2q_3-q_0q_1\bigr)^{2}+\bigl(q_1^{2}+q_2^{2}\bigr)^{2}\Bigr]}{|q|^{4}}.
\label{eq:HhExplicit}
\end{align}

\label{thm:domainQ}
For every $q\ne0$,
\begin{align}\label{eq:Kdef}
|q|^{-2}R(q)\in\mathcal{D}(\tau)
\quad\Longleftrightarrow\quad
Q_{\mathrm h}(q)\ge0\ \text{ and }\ U_{\mathrm h}(q)\ge0 .
\end{align}

\label{def:certificate}
Let $\tau\in(0,2)$ with $\tau^{2}\in\mathbb{Q}$, let $L\in\mathbb N$, and let $T^{*}\in\mathbb{Q}$. A
\emph{certificate at $(\tau,L,T^{*})$} consists of, for each $\ell=1,\dots,L$:
\begin{itemize}
\item a diagonal matrix $D_\ell=\operatorname{diag}(w^\ell_1,\dots,w^\ell_{2\ell+1})$ with $w^\ell_i\in\mathbb{Q}_{>0}$,
\item a symmetric matrix $C_\ell\in\mathbb{Q}^{(2\ell+1)\times(2\ell+1)}$, and
\item a matrix $T^{\ell}_{\mathrm h}$ of polynomials in $\mathbb{Q}[q_0,q_1,q_2,q_3]$ of size
$(2\ell+1)\times(2\ell+1)$,
\end{itemize}
subject to the following hypotheses. Set
\begin{align}
P(q)&=\sum_{\ell=1}^{L}\bigl(|q|^{2}\bigr)^{L-\ell}
\sum_{i,j=1}^{2\ell+1}\frac{(C_\ell)_{ij}\,(T^{\ell}_{\mathrm h})_{ij}(q)}{w^{\ell}_j},
\label{eq:P}\\
G(q)&=-\bigl(|q|^{2}\bigr)^{L}-P(q). \label{eq:G}
\end{align}
\begin{enumerate}[leftmargin=3.2em,label=\textup{(H\arabic*)}]
\item\label{H:hom} \emph{(Homogeneity.)} Every entry of $T^{\ell}_{\mathrm h}$ is a homogeneous
polynomial of degree $2\ell$.
\item\label{H:mult} \emph{(Multiplicativity.)}
$T^{\ell}_{\mathrm h}(p*q)=T^{\ell}_{\mathrm h}(p)\,T^{\ell}_{\mathrm h}(q)$ as an identity in
$\mathbb{Q}[p,q]$.
\item\label{H:orth} \emph{(Orthogonality.)}
$T^{\ell}_{\mathrm h}(q)^{\top}D_\ell\,T^{\ell}_{\mathrm h}(q)=\bigl(|q|^{2}\bigr)^{2\ell}D_\ell$ as
an identity in $\mathbb{Q}[q]$.
\item\label{H:psd} \emph{(Positive semidefiniteness.)} $C_\ell$ is positive semidefinite.
\item\label{H:trace} \emph{(Trace.)} $\sum_{\ell=1}^{L}\operatorname{tr}\bigl(D_\ell^{-1}C_\ell\bigr)=T^{*}$.
\item\label{H:cover} \emph{(Cover.)} $G(q)\ge0$ for every $q\in\mathcal{D}_{\mathrm h}(\tau)$.
\end{enumerate}

\label{lem:domPSD}
Let $E\in\mathbb{R}^{n\times n}$ be symmetric with
$E_{ii}\ge\sum_{j\ne i}|E_{ij}|$ for every $i$. Then $E\succeq0$.

\label{thm:sos}
Fix a certificate at $(\tau,L,T^{*})$, let $G$ be its cover polynomial \eqref{eq:G}, and let
$Q_{\mathrm h}$, $U_{\mathrm h}$ be as in \eqref{eq:Qh}--\eqref{eq:Uh}. Suppose we are given an
integer $k\ge0$ with $L+k\ge4$ and four symmetric positive semidefinite matrices with rational
entries,
\begin{align*}
\Sigma_0\in\mathbb{Q}^{n_{L+k}\times n_{L+k}},\quad
\Sigma_1,\Sigma_2\in\mathbb{Q}^{n_{L+k-2}\times n_{L+k-2}},\quad
\Sigma_3\in\mathbb{Q}^{n_{L+k-4}\times n_{L+k-4}},
\end{align*}
such that, with $\sigma_a=\mathfrak m^{\top}\Sigma_a\,\mathfrak m$ formed from the monomial vector
of the matching degree, the identity
\begin{align}\label{eq:sos}
\bigl(|q|^{2}\bigr)^{k}\,G
\;=\;\sigma_0\;+\;\sigma_1\,U_{\mathrm h}\;+\;\sigma_2\,Q_{\mathrm h}
\;+\;\sigma_3\,U_{\mathrm h}\,Q_{\mathrm h}
\end{align}
holds in $\mathbb{Q}[q_0,q_1,q_2,q_3]$. Then hypothesis \ref{H:cover} holds.
